				? \`\${key}:\\n\${value.replace(/\\n$/u, "")}\`
				: \`\${key}: \${value}\`;
		}
		return formatValue(key, value);
	});
	const text = lines.join("\\n");
	return text.length > ARGUMENTS_LENGTH
		? \`\${text.slice(0, ARGUMENTS_LENGTH - 1)}…\`
		: text;
}` },
